132:   pub fn new<'env>(env: &'env Env, mut this: This<'c>, width: i32, height: i32) -> Result<Self> {
133:     // Default fallback of canvas on browser and skia-canvas is 350x150
134:     let width = (if width <= 0 { 350 } else { width }) as u32;
135:     let height = (if height <= 0 { 150 } else { height }) as u32;
136:     let ctx = Self::create_context(env, width, height)?;
