184:   #[napi]
185:   pub fn get_context<'env>(
186:     &mut self,
187:     this: This,
188:     context_type: String,
189:     attrs: Option<CanvasRenderingContext2DAttributes>,
190:   ) -> Result<Unknown<'env>> {
191:     if context_type != "2d" {
192:       return Err(Error::new(
193:         Status::InvalidArg,
194:         format!("{context_type} is not supported"),
195:       ));
196:     }
197:     let context_2d = &mut self.ctx.context;
198:     if !attrs.as_ref().and_then(|a| a.alpha).unwrap_or(true) {
199:       let mut fill_paint = context_2d.fill_paint()?;
200:       fill_paint.set_color(255, 255, 255, 255);
201:       context_2d.alpha = false;
202:       context_2d.surface.draw_rect(
203:         0f32,
204:         0f32,
205:         self.width as f32,
206:         self.height as f32,
207:         &fill_paint,
208:       );
209:     }
210:     let color_space = attrs
211:       .and_then(|a| a.color_space)
212:       .and_then(|cs| ColorSpace::from_str(&cs).ok())
213:       .unwrap_or_default();
214:     context_2d.color_space = color_space;
215:     this.get_named_property("ctx")
216:   }
