32:     width_or_data: Either4<u32, Uint8ClampedArray, Uint16Array, Float32Array>,
33:     width_or_height: u32,
34:     height_or_settings: Option<Either<u32, Settings>>,
35:     maybe_settings: Option<Settings>,
36:   ) -> Result<Self> {
37:     match width_or_data {
38:       Either4::A(width) => {
39:         let height = width_or_height;
40:         let color_space = match height_or_settings {
41:           Some(Either::B(settings)) => {
42:             ColorSpace::from_str(&settings.color_space).unwrap_or_default()
43:           }
44:           _ => ColorSpace::default(),
45:         };
46:         let arraybuffer_length = (width * height * 4) as usize;
47:         let mut data_buffer = vec![0; arraybuffer_length];
48:         let data_ptr = data_buffer.as_mut_ptr();
49:         let data_object = Uint8ClampedSlice::from_data(&env, data_buffer)?;
50:         this.define_properties(&[Property::new()
51:           .with_utf8_name("data")?
52:           .with_value(&data_object)
53:           .with_property_attributes(
54:             PropertyAttributes::Enumerable | PropertyAttributes::Configurable,
55:           )])?;
56:         Ok(ImageData {
57:           width: width as usize,
58:           height: height as usize,
59:           color_space,
60:           data: data_ptr,
61:         })
62:       }
63:       Either4::B(data_object) => {
64:         // Uint8ClampedArray - each pixel takes 4 bytes
65:         let input_data_length = data_object.len();
66:         let width = width_or_height;
67:         let height = match &height_or_settings {
68:           Some(Either::A(height)) => *height,
69:           _ => (input_data_length as u32) / 4 / width,
70:         };
71:         if height * width * 4 != data_object.len() as u32 {
72:           return Err(Error::new(
73:             Status::InvalidArg,
74:             "Index or size is negative or greater than the allowed amount".to_owned(),
75:           ));
76:         }
77:         // https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/createImageData
78:         // An existing ImageData object from which to copy the width and height.
79:         let mut cloned_data = Uint8ClampedSlice::from_data(&env, data_object.to_vec())?;
80:         let data = unsafe { cloned_data.as_mut() }.as_mut_ptr();
81:         this.define_properties(&[Property::new()
82:           .with_utf8_name("data")?
83:           .with_value(&cloned_data)
84:           .with_property_attributes(
85:             PropertyAttributes::Enumerable | PropertyAttributes::Configurable,
86:           )])?;
87:         let color_space = maybe_settings
88:           .and_then(|settings| ColorSpace::from_str(&settings.color_space).ok())
89:           .unwrap_or_default();
90:         Ok(ImageData {
91:           width: width as usize,
92:           height: height as usize,
93:           color_space,
94:           data,
95:         })
96:       }
97:       Either4::C(data_object) => {
98:         // Uint16Array - each pixel takes 4 elements (RGBA), 2 bytes per element
99:         let input_data_length = data_object.len();
100:         let width = width_or_height;
101:         let height = match &height_or_settings {
102:           Some(Either::A(height)) => *height,
103:           _ => (input_data_length as u32) / 4 / width,
104:         };
105:         if height * width * 4 != data_object.len() as u32 {
106:           return Err(Error::new(
107:             Status::InvalidArg,
108:             "Index or size is negative or greater than the allowed amount".to_owned(),
109:           ));
110:         }
111:         // Convert Uint16Array to Uint8ClampedArray
112:         let mut u8_data = vec![0u8; width as usize * height as usize * 4];
113:         for (i, &val) in data_object.as_ref().iter().enumerate() {
114:           // Convert from 16-bit (0-65535) to 8-bit (0-255)
115:           u8_data[i] = ((val as u32 * 255 + 32767) / 65535) as u8;
116:         }
117:         let mut cloned_data = Uint8ClampedSlice::from_data(&env, u8_data)?;
118:         let data = unsafe { cloned_data.as_mut() }.as_mut_ptr();
119:         this.define_properties(&[Property::new()
120:           .with_utf8_name("data")?
121:           .with_value(&cloned_data)
122:           .with_property_attributes(
123:             PropertyAttributes::Enumerable | PropertyAttributes::Configurable,
124:           )])?;
125:         let color_space = maybe_settings
126:           .and_then(|settings| ColorSpace::from_str(&settings.color_space).ok())
127:           .unwrap_or_default();
128:         Ok(ImageData {
129:           width: width as usize,
130:           height: height as usize,
131:           color_space,
132:           data,
133:         })
134:       }
135:       Either4::D(data_object) => {
136:         // Float32Array - each pixel takes 4 elements (RGBA), 4 bytes per element
137:         let input_data_length = data_object.len();
138:         let width = width_or_height;
139:         let height = match &height_or_settings {
140:           Some(Either::A(height)) => *height,
141:           _ => (input_data_length as u32) / 4 / width,
142:         };
143:         if height * width * 4 != data_object.len() as u32 {
144:           return Err(Error::new(
145:             Status::InvalidArg,
146:             "Index or size is negative or greater than the allowed amount".to_owned(),
147:           ));
148:         }
149:         // Convert Float32Array to Uint8ClampedArray
150:         let mut u8_data = vec![0u8; width as usize * height as usize * 4];
151:         for (i, &val) in data_object.as_ref().iter().enumerate() {
152:           // Clamp float values to [0.0, 1.0] and convert to 8-bit (0-255)
153:           let clamped = val.clamp(0.0, 1.0);
154:           u8_data[i] = (clamped * 255.0).round() as u8;
155:         }
156:         let mut cloned_data = Uint8ClampedSlice::from_data(&env, u8_data)?;
157:         let data = unsafe { cloned_data.as_mut() }.as_mut_ptr();
158:         this.define_properties(&[Property::new()
159:           .with_utf8_name("data")?
160:           .with_value(&cloned_data)
161:           .with_property_attributes(
162:             PropertyAttributes::Enumerable | PropertyAttributes::Configurable,
163:           )])?;
164:         let color_space = maybe_settings
165:           .and_then(|settings| ColorSpace::from_str(&settings.color_space).ok())
166:           .unwrap_or_default();
167:         Ok(ImageData {
168:           width: width as usize,
169:           height: height as usize,
170:           color_space,
171:           data,
172:         })
173:       }
174:     }
175:   }
176: 
177:   #[napi(getter)]
178:   pub fn get_width(&self) -> u32 {
179:     self.width as u32
180:   }
181: 
182:   #[napi(getter)]
183:   pub fn get_height(&self) -> u32 {
184:     self.height as u32
185:   }
186: }
