188: #[napi(custom_finalize)]
189: pub struct Image {
190:   pub(crate) bitmap: Option<Bitmap>,
191:   pub(crate) complete: bool,
192:   pub(crate) alt: String,
193:   pub(crate) current_src: Option<String>,
194:   width: f64,
195:   height: f64,
196:   // Natural dimensions - extracted from image header, available before full decode
197:   natural_width: f64,
198:   natural_height: f64,
199:   pub(crate) need_regenerate_bitmap: bool,
200:   pub(crate) is_svg: bool,
201:   pub(crate) color_space: ColorSpace,
202:   pub(crate) src: Option<Either<Uint8Array, String>>,
203:   // read data from file path
204:   file_content: Option<Vec<u8>>,
205:   // take ownership of avif image, let it be dropped when image is dropped
206:   _avif_image_ref: Option<AvifImage>,
207:   // Bytes accounted to V8 via adjust_external_memory for this image
208:   accounted_bytes: i64,
209:   // Generation counter to handle overlapping loads
210:   load_generation: u64,
211: 
212:   decoder_task: Option<ObjectRef>,
213: }
214: 
215: impl ObjectFinalize for Image {
216:   fn finalize(self, env: Env) -> Result<()> {
217:     if self.accounted_bytes != 0 {
218:       env.adjust_external_memory(-self.accounted_bytes)?;
219:     }
220:     if let Some(decoder_task) = self.decoder_task {
221:       decoder_task.unref(&env)?;
222:     }
223:     Ok(())
224:   }
225: }
226: 
227: #[napi]
228: impl Image {
229:   #[napi(constructor)]
230:   pub fn new(width: Option<f64>, height: Option<f64>, color_space: Option<String>) -> Result<Self> {
231:     let width = width.unwrap_or(-1.0);
232:     let height = height.unwrap_or(-1.0);
233:     let color_space = color_space
234:       .and_then(|c| ColorSpace::from_str(&c).ok())
235:       .unwrap_or_default();
236:     Ok(Image {
237:       complete: true,
238:       bitmap: None,
239:       alt: "".to_string(),
240:       current_src: None,
241:       width,
242:       height,
243:       natural_width: 0.0,
244:       natural_height: 0.0,
245:       need_regenerate_bitmap: false,
246:       is_svg: false,
247:       color_space,
248:       src: None,
249:       file_content: None,
250:       _avif_image_ref: None,
251:       accounted_bytes: 0,
252:       load_generation: 0,
253:       decoder_task: None,
254:     })
255:   }
256: 
257:   #[napi(getter)]
258:   pub fn get_width(&self) -> f64 {
259:     if self.width >= 0.0 { self.width } else { 0.0 }
260:   }
261: 
262:   #[napi(setter)]
263:   pub fn set_width(&mut self, width: f64) {
264:     if (width - self.width).abs() > f64::EPSILON {
265:       self.width = width;
266:       self.need_regenerate_bitmap = true;
267:     }
268:   }
269: 
270:   #[napi(getter)]
271:   pub fn get_natural_width(&self) -> f64 {
272:     // Return stored natural_width (set from imagesize header parsing)
273:     // Falls back to bitmap dimensions if natural_width not set
274:     if self.natural_width > 0.0 {
275:       self.natural_width
276:     } else {
277:       self.bitmap.as_ref().map(|b| b.0.width).unwrap_or(0) as f64
278:     }
279:   }
280: 
281:   #[napi(getter)]
282:   pub fn get_height(&self) -> f64 {
283:     if self.height >= 0.0 { self.height } else { 0.0 }
284:   }
285: 
286:   #[napi(setter)]
287:   pub fn set_height(&mut self, height: f64) {
288:     if (height - self.height).abs() > f64::EPSILON {
289:       self.height = height;
290:       self.need_regenerate_bitmap = true;
291:     }
292:   }
293: 
294:   #[napi(getter)]
295:   pub fn get_natural_height(&self) -> f64 {
296:     // Return stored natural_height (set from imagesize header parsing)
297:     // Falls back to bitmap dimensions if natural_height not set
298:     if self.natural_height > 0.0 {
299:       self.natural_height
300:     } else {
301:       self.bitmap.as_ref().map(|b| b.0.height).unwrap_or(0) as f64
302:     }
303:   }
304: 
305:   #[napi(getter)]
306:   pub fn get_complete(&self) -> bool {
307:     self.complete
308:   }
309: 
310:   #[napi(getter)]
311:   pub fn get_current_src(&self) -> Option<&str> {
312:     self.current_src.as_deref()
313:   }
314: 
315:   #[napi(getter)]
316:   pub fn get_alt(&self) -> String {
317:     self.alt.clone()
318:   }
319: 
320:   #[napi(setter)]
321:   pub fn set_alt(&mut self, alt: String) {
322:     self.alt = alt;
323:   }
324: 
325:   #[napi(getter)]
326:   pub fn get_src(&mut self) -> Option<Either<&mut Uint8Array, &str>> {
327:     match self.src.as_mut() {
328:       Some(Either::A(d)) => Some(Either::A(d)),
329:       Some(Either::B(s)) => Some(Either::B(s.as_str())),
330:       None => None,
331:     }
332:   }
333: 
334:   #[napi(setter)]
335:   pub fn set_src(&mut self, env: Env, this: This, raw_data: Unknown) -> Result<()> {
336:     let data = match raw_data.get_type()? {
337:       ValueType::Object if (raw_data.is_buffer()? || raw_data.is_typedarray()?) => {
338:         let data: Uint8Array = unsafe { raw_data.cast() }?;
339:         self.src.insert(Either::A(data))
340:       }
341:       ValueType::String => {
342:         let string = unsafe { raw_data.cast()? };
343:         self.src.insert(Either::B(string))
344:       }
345:       _ => return Ok(()),
346:     };
347:     // Increment generation FIRST to invalidate all in-flight loads
348:     // This must happen for BOTH empty and valid src to prevent race conditions
349:     self.load_generation = self.load_generation.wrapping_add(1);
350: 
351:     // Check if src is empty per HTML spec.
352:     // The previous `< 5` byte heuristic incorrectly silenced tiny invalid buffers
353:     // (e.g. Buffer.from([1])), causing loadImage() to hang. Such buffers must
354:     // fall through to the async decoder, which reports them via onerror.
355:     // See https://github.com/Brooooooklyn/canvas/issues/1255
356:     let is_empty = match &data {
357:       Either::A(buffer) => buffer.is_empty(),
358:       Either::B(string) => string.is_empty(),
359:     };
360: 
361:     if is_empty {
362:       // HTML spec: empty src = clear state, complete=true, NO events
363:       self.src = None;
364:       self.current_src = None;
365:       self.width = -1.0;
366:       self.height = -1.0;
367:       self.natural_width = 0.0;
368:       self.natural_height = 0.0;
369:       self.bitmap = None;
370:       self.file_content = None;
371:       self._avif_image_ref = None;
372:       self.complete = true;
373:       self.is_svg = false;
374:       self.need_regenerate_bitmap = false;
375: 
376:       // Clear decoder_task so decode() returns fresh resolved promise
377:       if let Some(previous_task) = self.decoder_task.take() {
378:         previous_task.unref(&env)?;
379:       }
380: 
381:       // Clear external memory accounting
382:       if self.accounted_bytes != 0 {
383:         env.adjust_external_memory(-self.accounted_bytes)?;
384:         self.accounted_bytes = 0;
385:       }
386:       return Ok(());
387:     }
388: 
389:     // For Buffer: load synchronously (dimensions + events), decode bitmap synchronously
390:     // This matches node-canvas behavior where onerror/onload fire synchronously
391:     if let Either::A(buffer) = data {
392:       let buffer_data = buffer.as_ref();
393:       let length = buffer_data.len();
394: 
395:       // Check if it's SVG (imagesize doesn't support SVG)
396:       let is_svg = is_svg_image(buffer_data, length);
397:       // Try to extract dimensions from image header using imagesize (fast, no full decode)
398:       let (img_width, img_height, is_valid_image) = if is_svg {
399:         // For SVG, we'll get dimensions after decode; for invalid images, we'll error
400:         (0.0, 0.0, false)
401:       } else if let Ok(size) = imagesize::blob_size(buffer_data) {
402:         (size.width as f64, size.height as f64, true)
403:       } else {
404:         (0.0, 0.0, false)
405:       };
406: 
407:       if is_valid_image || is_svg {
408:         // Set natural dimensions (sync, from header)
409:         // For SVG (where imagesize fails), leave at 0 - will be set after decode
410:         self.natural_width = img_width;
411:         self.natural_height = img_height;
412: 
413:         // Set width/height if not explicitly set (auto sizing)
414:         // For SVG, keep at -1.0 to signal that we need auto-sizing after decode
415:         if is_valid_image {
416:           if (self.width - -1.0).abs() < f64::EPSILON {
417:             self.width = img_width;
418:           }
419:           if (self.height - -1.0).abs() < f64::EPSILON {
420:             self.height = img_height;
421:           }
422:         }
423: 
424:         // For SVG, we need to decode synchronously to get dimensions
425:         if is_svg {
426:           let font = get_font().map_err(SkError::from)?;
427:           if (self.width - -1.0).abs() > f64::EPSILON && (self.height - -1.0).abs() > f64::EPSILON {
428:             if let Some(bitmap) = Bitmap::from_svg_data_with_custom_size(
429:               buffer_data.as_ptr(),
430:               length,
431:               self.width as f32,
432:               self.height as f32,
433:               self.color_space,
434:               &font,
435:             ) {
436:               self.is_svg = true;
437:               self.natural_width = bitmap.0.width as f64;
438:               self.natural_height = bitmap.0.height as f64;
439:               let new_bytes = (bitmap.0.width as i64) * (bitmap.0.height as i64) * 4;
440:               self.adjust_external_memory_if_need(&env, new_bytes)?;
441:               self.bitmap = Some(bitmap);
442:             } else {
443:               // Invalid SVG - fire onerror synchronously
444:               // Clear prior image state to prevent stale data from being drawn
445:               // Reset width/height to auto (-1.0) so getters return 0 for broken image
446:               self.complete = true;
447:               self.width = -1.0;
448:               self.height = -1.0;
449:               self.natural_width = 0.0;
450:               self.natural_height = 0.0;
451:               self.bitmap = None;
452:               self.file_content = None;
453:               self._avif_image_ref = None;
454:               self.is_svg = false;
455:               self.need_regenerate_bitmap = false;
456:               if self.accounted_bytes != 0 {
457:                 env.adjust_external_memory(-self.accounted_bytes)?;
458:                 self.accounted_bytes = 0;
459:               }
460: 
461:               let onerror = this.get_named_property_unchecked::<Unknown>("onerror")?;
462:               let error = env.create_error(Error::new(Status::InvalidArg, "Invalid SVG image"))?;
463:               if onerror.get_type()? == ValueType::Function {
464:                 let onerror_func: Function<Object, Unknown> = Function::from_unknown(onerror)?;
465:                 onerror_func.apply(this, error)?;
466:               }
467:               if let Some(previous_task) = self.decoder_task.replace(
468:                 PromiseRaw::resolve(&env, error)?
469:                   .coerce_to_object()?
470:                   .create_ref()?,
471:               ) {
472:                 previous_task.unref(&env)?;
473:               }
474:               return Ok(());
475:             }
476:           } else {
477:             // SVG without explicit dimensions - use default decode
478:             match Bitmap::from_svg_data(buffer_data.as_ptr(), length, self.color_space, &font) {
479:               Some(Ok(bitmap)) => {
480:                 self.is_svg = true;
481:                 self.natural_width = bitmap.0.width as f64;
482:                 self.natural_height = bitmap.0.height as f64;
483:                 self.width = bitmap.0.width as f64;
484:                 self.height = bitmap.0.height as f64;
485:                 let new_bytes = (bitmap.0.width as i64) * (bitmap.0.height as i64) * 4;
486:                 self.adjust_external_memory_if_need(&env, new_bytes)?;
487:                 self.bitmap = Some(bitmap);
488:               }
489:               Some(Err(_)) => {
490:                 // Invalid SVG - fire onerror synchronously
491:                 // Clear prior image state to prevent stale data from being drawn
492:                 // Reset width/height to auto (-1.0) so getters return 0 for broken image
493:                 self.complete = true;
494:                 self.width = -1.0;
495:                 self.height = -1.0;
496:                 self.natural_width = 0.0;
497:                 self.natural_height = 0.0;
498:                 self.bitmap = None;
499:                 self.file_content = None;
500:                 self._avif_image_ref = None;
501:                 self.is_svg = false;
502:                 self.need_regenerate_bitmap = false;
503:                 if self.accounted_bytes != 0 {
504:                   env.adjust_external_memory(-self.accounted_bytes)?;
505:                   self.accounted_bytes = 0;
506:                 }
507: 
508:                 let onerror = this.get_named_property_unchecked::<Unknown>("onerror")?;
509:                 let error =
510:                   env.create_error(Error::new(Status::InvalidArg, "Invalid SVG image"))?;
511:                 if onerror.get_type()? == ValueType::Function {
512:                   let onerror_func: Function<Object, Unknown> = Function::from_unknown(onerror)?;
513:                   onerror_func.apply(this, error)?;
514:                 }
515:                 if let Some(previous_task) = self.decoder_task.replace(
516:                   PromiseRaw::resolve(&env, error)?
517:                     .coerce_to_object()?
518:                     .create_ref()?,
519:                 ) {
520:                   previous_task.unref(&env)?;
521:                 }
522:                 return Ok(());
523:               }
524:               None => {
525:                 // SVG has no dimensions - valid but empty, still fire onload
526:                 self.is_svg = true;
527:               }
528:             }
529:           }
530:         }
531: 
532:         // Set complete = true immediately for Buffer sources (jsdom compatibility).
533:         // NOTE: For non-SVG buffers, complete=true means dimensions are available from header
534:         // parsing, but bitmap decoding is still async. This differs from the HTML spec where
535:         // complete implies the image is fully decoded. Callers should either:
536:         // 1. Use the onload handler (fires after bitmap decode) before drawImage/createPattern
537:         // 2. Call await image.decode() before drawing
538:         // Calling drawImage while complete=true but before decode finishes will silently no-op.
539:         self.complete = true;
540: 
541:         // For non-SVG images, spawn async bitmap decoding task.
542:         // onload fires in resolve() after bitmap is decoded, so drawImage works in onload handler.
543:         if !is_svg {
544:           // Clear previous bitmap and related state to prevent stale renders during async decode.
545:           // Without this, drawImage could render the old image until the new decode completes.
546:           self.bitmap = None;
547:           self._avif_image_ref = None;
548:           self.file_content = None;
549:           self.is_svg = false;
550:           self.need_regenerate_bitmap = false;
551:           if self.accounted_bytes != 0 {
552:             env.adjust_external_memory(-self.accounted_bytes)?;
553:             self.accounted_bytes = 0;
554:           }
555: 
556:           let task = BitmapDecoder {
557:             width: self.width,
558:             height: self.height,
559:             this_ref: this.create_ref()?,
560:             generation: self.load_generation,
561:             color_space: self.color_space,
562:             data: Some(Either::A(unsafe { raw_data.cast()? })),
563:             file_content: None,
564:             fire_events: true, // Fire onload after decode completes
565:             original_url: None,
566:           };
567:           let decode_task = env.spawn(task)?;
568:           let promise_object = decode_task.promise_object();
569: 
570:           if let Some(previous_task) = self
571:             .decoder_task
572:             .replace(promise_object.coerce_to_object()?.create_ref()?)
573:           {
574:             previous_task.unref(&env)?;
575:           }
576:         } else {
577:           // For SVG: bitmap already decoded synchronously above, fire onload now
578:           self.current_src = Some("[Buffer]".to_string());
579: 
580:           // Set decoder_task to resolved promise so decode() works correctly
581:           if let Some(previous_task) = self.decoder_task.replace(
582:             PromiseRaw::resolve(&env, ())?
583:               .coerce_to_object()?
584:               .create_ref()?,
585:           ) {
586:             previous_task.unref(&env)?;
587:           }
588: 
589:           let onload = this.get_named_property_unchecked::<Unknown>("onload")?;
590:           if onload.get_type()? == ValueType::Function {
591:             let onload_func: Function<(), ()> = Function::from_unknown(onload)?;
592:             onload_func.apply(this, ())?;
593:           }
594:         }
595: 
596:         return Ok(());
597:       } else {
598:         // imagesize failed (format not supported by imagesize, e.g. BMP, ICO, TIFF)
599:         // Fall through to async decode - let Skia/infer determine validity.
600:         // NOTE: complete=true but dimensions are 0 until decode completes.
601:         // Same caveats apply as above: use onload or decode() before drawing.
602:         self.complete = true;
603: 
604:         // Clear previous state to avoid exposing stale data from previous loads.
605:         // Dimensions will be set by resolve() after successful decode.
606:         self.natural_width = 0.0;
607:         self.natural_height = 0.0;
608:         self.bitmap = None;
609:         self._avif_image_ref = None;
610:         self.file_content = None;
611:         self.is_svg = false;
612:         self.need_regenerate_bitmap = false;
613:         if self.accounted_bytes != 0 {
614:           env.adjust_external_memory(-self.accounted_bytes)?;
615:           self.accounted_bytes = 0;
616:         }
617: 
618:         let task = BitmapDecoder {
619:           width: self.width,
620:           height: self.height,
621:           this_ref: this.create_ref()?,
622:           generation: self.load_generation,
623:           color_space: self.color_space,
624:           data: Some(Either::A(unsafe { raw_data.cast()? })),
625:           file_content: None,
626:           fire_events: true,
627:           original_url: None,
628:         };
629:         let decode_task = env.spawn(task)?;
630:         let promise_object = decode_task.promise_object();
631: 
632:         if let Some(previous_task) = self
633:           .decoder_task
634:           .replace(promise_object.coerce_to_object()?.create_ref()?)
635:         {
636:           previous_task.unref(&env)?;
637:         }
638:         return Ok(());
639:       }
640:     }
641: 
642:     // Check if this is an HTTP/HTTPS URL - use fetch API instead of file read
643:     if let Either::B(url_string) = data
644:       && is_http_url(url_string)
645:     {
646:       self.complete = false;
647: 
648:       // Get global fetch function
649:       let global = env.get_global()?;
650:       let fetch_fn: Function<&str, Unknown> = global.get_named_property("fetch")?;
651: 
652:       // Store references for promise chain
653:       let url_clone = url_string.clone();
654:       let url_for_src = url_string.clone();
655:       // Create separate ObjectRefs for each callback, wrapped in Rc<Cell<Option<...>>>
656:       // so that whichever closure runs (then or catch) can clean up BOTH refs.
657:       // This prevents a memory leak: without this, on success the catch ref leaks
658:       // (catch never fires), and on error the then ref leaks (second then never fires).
659:       let this_ref_then_rc: Rc<Cell<Option<ObjectRef<false>>>> =
660:         Rc::new(Cell::new(Some(this.create_ref()?)));
661:       let this_ref_catch_rc: Rc<Cell<Option<ObjectRef<false>>>> =
662:         Rc::new(Cell::new(Some(this.create_ref()?)));
663: 
664:       let ref_then_for_then = this_ref_then_rc.clone();
665:       let ref_catch_for_then = this_ref_catch_rc.clone();
666:       let ref_then_for_catch = this_ref_then_rc.clone();
667:       let ref_catch_for_catch = this_ref_catch_rc.clone();
668:       let generation = self.load_generation;
669:       let width = self.width;
670:       let height = self.height;
671:       let color_space = self.color_space;
672: 
673:       // Call fetch(url)
674:       let fetch_promise = fetch_fn.call(url_clone.as_str())?;
675: 
676:       // Chain promises: fetch -> response.arrayBuffer() -> decode
677:       let promise = PromiseRaw::from_unknown(fetch_promise)?
678:         .then(move |ctx: CallbackContext<Object>| {
679:           // Check response.ok
680:           let response = ctx.value;
681:           let ok: bool = response.get_named_property("ok")?;
682:           if !ok {
683:             let status: u32 = response.get_named_property("status")?;
684:             return Err(Error::new(
685:               Status::GenericFailure,
686:               format!("HTTP request failed with status {}", status),
687:             ));
688:           }
689:           // Call response.arrayBuffer()
690:           let array_buffer_method: Function<(), Unknown> =
691:             response.get_named_property("arrayBuffer")?;
692:           array_buffer_method.apply(response, ())
693:         })?
694:         .then(move |ctx: CallbackContext<Unknown>| {
695:           // Convert ArrayBuffer to Uint8Array using JavaScript constructor
696:           let global = ctx.env.get_global()?;
697:           let uint8array_ctor: Function<Unknown, Unknown> =
698:             global.get_named_property("Uint8Array")?;
699:           let buffer_unknown = uint8array_ctor.new_instance(ctx.value)?;
700:           let buffer: Uint8Array = unsafe { buffer_unknown.cast()? };
701: 
702:           // Get Image instance and verify generation
703:           let this_ref = ref_then_for_then
704:             .take()
705:             .expect("then ObjectRef already taken");
706:           let this: Object = this_ref.get_value(&ctx.env)?;
707:           this_ref.unref(&ctx.env)?;
708:           // Also unref the catch ref since catch won't run on success
709:           if let Some(catch_ref) = ref_catch_for_then.take() {
710:             catch_ref.unref(&ctx.env)?;
711:           }
712: 
713:           let mut image_ptr = ptr::null_mut();
714:           check_status!(
715:             unsafe { sys::napi_unwrap(ctx.env.raw(), this.raw(), &mut image_ptr) },
716:             "Failed to unwrap Image from this"
717:           )?;
718:           let image = unsafe { &mut *image_ptr.cast::<Image>() };
719: 
720:           if generation != image.load_generation {
721:             // Stale load - return a resolved promise so the chain completes
722:             return PromiseRaw::resolve(&ctx.env, ())?.coerce_to_object();
723:           }
724: 
725:           // Spawn BitmapDecoder with downloaded buffer
726:           let decoder = BitmapDecoder {
727:             width,
728:             height,
729:             color_space,
730:             data: Some(Either::A(buffer)),
731:             file_content: None,
732:             this_ref: this.create_ref()?,
733:             generation,
734:             fire_events: true,
735:             original_url: Some(url_for_src),
736:           };
737:           let decode_task = ctx.env.spawn(decoder)?;
738:           // Return the decoder's promise so the chain waits for bitmap decoding to finish.
739:           // JS promise chaining automatically flattens returned promises (thenables).
740:           decode_task.promise_object().coerce_to_object()
741:         })?
742:         .catch(move |ctx: CallbackContext<Unknown>| {
743:           // Take the catch ref - may be None if the second .then() already unrefed it
744:           // (e.g. .then() succeeded in unrefing but then failed at spawn)
745:           let catch_ref = ref_catch_for_catch.take();
746:           // Also unref the then ref since second then didn't run on error
747:           if let Some(then_ref) = ref_then_for_catch.take() {
748:             then_ref.unref(&ctx.env)?;
749:           }
750: 
751:           // If catch_ref was already taken by the success path, the second .then()
752:           // already ran (and unrefed both refs) but errored afterwards.
753:           // We still need to handle the error but can skip state updates since
754:           // the .then() may have already spawned the decoder.
755:           let Some(catch_ref) = catch_ref else {
756:             return Ok(());
757:           };
758:           let this: Object = catch_ref.get_value(&ctx.env)?;
759:           catch_ref.unref(&ctx.env)?;
760: 
761:           // Get Image instance and update state
762:           let mut image_ptr = ptr::null_mut();
763:           check_status!(
764:             unsafe { sys::napi_unwrap(ctx.env.raw(), this.raw(), &mut image_ptr) },
765:             "Failed to unwrap Image from this"
766:           )?;
767:           let image = unsafe { &mut *image_ptr.cast::<Image>() };
768: 
769:           // Ignore stale errors from superseded loads
770:           if generation != image.load_generation {
771:             return Ok(());
772:           }
773: 
774:           image.complete = true;
775:           image.width = -1.0;
776:           image.height = -1.0;
777:           image.natural_width = 0.0;
778:           image.natural_height = 0.0;
779:           image.bitmap = None;
780:           image.file_content = None;
781:           image._avif_image_ref = None;
782:           image.is_svg = false;
783:           image.need_regenerate_bitmap = false;
784:           if image.accounted_bytes != 0 {
785:             ctx.env.adjust_external_memory(-image.accounted_bytes)?;
786:             image.accounted_bytes = 0;
787:           }
788: 
789:           let onerror = this.get_named_property_unchecked::<Unknown>("onerror")?;
790:           if onerror.get_type()? == ValueType::Function {
791:             let onerror_func: Function<Object, Unknown> = Function::from_unknown(onerror)?;
792:             let error_msg: String = ctx
793:               .value
794:               .coerce_to_string()
795:               .and_then(|s: JsString| s.into_utf8())
796:               .and_then(|s: JsStringUtf8| s.into_owned())
797:               .unwrap_or_else(|_| "Network error".to_string());
798:             let error_obj = ctx
799:               .env
800:               .create_error(Error::new(Status::GenericFailure, error_msg))?;
801:             onerror_func.apply(this, error_obj)?;
802:           }
803:           Ok(())
804:         })?;
805: 
806:       // Store promise reference
807:       if let Some(previous_task) = self
808:         .decoder_task
809:         .replace(promise.coerce_to_object()?.create_ref()?)
810:       {
811:         previous_task.unref(&env)?;
812:       }
813:       return Ok(());
814:     }
815: 
816:     // For file path/URL: use existing async loading (complete = false until loaded)
817:     self.complete = false;
818: 
819:     // NOTE: current_src is NOT set here - only set in resolve() after successful load
820:     // On failure, it remains the last successful value (per HTML spec).
821: 
822:     let decoder = BitmapDecoder {
823:       width: self.width,
824:       height: self.height,
825:       color_space: self.color_space,
826:       data: Some(unsafe { raw_data.cast()? }),
827:       file_content: None,
828:       this_ref: this.create_ref()?,
829:       generation: self.load_generation,
830:       fire_events: true,
831:       original_url: None,
832:     };
833:     let task_output = env.spawn(decoder)?;
834:     let promise_object = task_output.promise_object();
835:     if let Some(previous_task) = self
836:       .decoder_task
837:       .replace(promise_object.coerce_to_object()?.create_ref()?)
838:     {
839:       previous_task.unref(&env)?;
840:     }
841:     Ok(())
842:   }
843: 
844:   #[napi(ts_return_type = "Promise<void>")]
845:   pub fn decode<'env>(&self, env: &'env Env) -> Result<Object<'env>> {
846:     if let Some(promise_ref) = self.decoder_task.as_ref() {
847:       // Return the stored promise reference
848:       let promise = promise_ref.get_value(env)?;
849:       return PromiseRaw::resolve(env, promise)?
850:         .then(|ctx| {
851:           if ctx.value.is_error()? {
852:             ctx.env.throw(ctx.value)?;
853:           }
854:           Ok(ctx.value)
855:         })?
856:         .coerce_to_object();
857:     }
858: 
859:     PromiseRaw::resolve(env, ())?.coerce_to_object()
860:   }
