862:   pub(crate) fn regenerate_bitmap_if_need(&mut self, env: &Env) -> Result<()> {
863:     if !self.need_regenerate_bitmap || !self.is_svg || self.src.is_none() {
864:       return Ok(());
865:     }
866: 
867:     if let Some(data) = self.file_content.as_deref() {
868:       let font = get_font().map_err(SkError::from)?;
869:       self.bitmap = Bitmap::from_svg_data_with_custom_size(
870:         data.as_ptr(),
871:         data.len(),
872:         self.width as f32,
873:         self.height as f32,
874:         self.color_space,
875:         &font,
876:       );
877:       if let Some(bmp) = &self.bitmap {
878:         let new_bytes = (bmp.0.width as i64) * (bmp.0.height as i64) * 4;
879:         self.adjust_external_memory_if_need(env, new_bytes)?;
880:       }
881:       self.need_regenerate_bitmap = false;
882:       return Ok(());
883:     }
884:     if let Some(data) = self.src.as_ref() {
885:       let font = get_font().map_err(SkError::from)?;
886:       self.bitmap = Bitmap::from_svg_data_with_custom_size(
887:         data.as_ref().as_ptr(),
888:         data.as_ref().len(),
889:         self.width as f32,
890:         self.height as f32,
891:         self.color_space,
892:         &font,
893:       );
894:       if let Some(bmp) = &self.bitmap {
895:         let new_bytes = (bmp.0.width as i64) * (bmp.0.height as i64) * 4;
896:         self.adjust_external_memory_if_need(env, new_bytes)?;
897:       }
898:       self.need_regenerate_bitmap = false;
899:     }
900:     Ok(())
901:   }
902: 
903:   fn adjust_external_memory_if_need(&mut self, env: &Env, new_bytes: i64) -> Result<()> {
904:     let delta = new_bytes - self.accounted_bytes;
905:     if delta != 0 {
906:       env.adjust_external_memory(delta)?;
907:       self.accounted_bytes = new_bytes;
908:     }
909:     Ok(())
910:   }
911: }
