913: fn is_svg_image(data: &[u8], length: usize) -> bool {
914:   let mut is_svg = false;
915:   if length >= 11 {
916:     for i in 3..length {
917:       if '<' == data[i - 3] as char {
918:         match data[i - 2] as char {
919:           '?' | '!' => continue,
920:           's' => {
921:             is_svg = 'v' == data[i - 1] as char && 'g' == data[i] as char;
922:             break;
923:           }
924:           _ => {
925:             is_svg = false;
926:           }
927:         }
928:       }
929:     }
930:   }
931:   is_svg
932: }
933: 
934: fn is_http_url(s: &str) -> bool {
935:   s.starts_with("http://") || s.starts_with("https://")
936: }
