938: pub(crate) struct DecodedBitmap {
939:   bitmap: DecodeStatus,
940:   width: f64,
941:   height: f64,
942: }
943: 
944: unsafe impl Send for DecodedBitmap {}
945: 
946: struct BitmapInfo {
947:   data: Bitmap,
948:   is_svg: bool,
949:   #[allow(dead_code)]
950:   decoded_image: Option<AvifImage>,
951: }
952: 
953: enum DecodeStatus {
954:   Ok(BitmapInfo),
955:   Empty,
956:   InvalidSvg,
957:   InvalidImage,
958: }
959: 
960: struct BitmapDecoder {
961:   width: f64,
962:   height: f64,
963:   color_space: ColorSpace,
964:   data: Option<Either<Uint8Array, String>>,
965:   // data from file path
966:   file_content: Option<Vec<u8>>,
967:   this_ref: ObjectRef,
968:   // Generation counter to detect stale loads
969:   generation: u64,
970:   // Whether to fire events in the Task resolve/reject
971:   // The `src = Buffer` fire events in the `set_src`, so it doesn't need to fire events in the Task resolve/reject
972:   fire_events: bool,
973:   // Preserve original HTTP URL for currentSrc when data is downloaded bytes
974:   original_url: Option<String>,
975: }
976: 
977: impl<'env> ScopedTask<'env> for BitmapDecoder {
978:   type Output = DecodedBitmap;
979:   type JsValue = Unknown<'env>;
980: 
981:   fn compute(&mut self) -> Result<Self::Output> {
982:     let data_ref = match self.data.as_ref() {
983:       Some(Either::A(data)) => Cow::Borrowed(data.as_ref()),
984:       Some(Either::B(path_or_svg)) => {
985:         if path_or_svg.starts_with("data:") {
986:           Cow::Borrowed(path_or_svg.as_bytes())
987:         } else {
988:           match std::fs::read(path_or_svg) {
989:             Ok(file_content) => {
990:               self.file_content = Some(file_content);
991:               Cow::Borrowed(self.file_content.as_ref().unwrap().as_ref())
992:             }
993:             Err(io_err) => {
994:               return Err(Error::new(
995:                 Status::GenericFailure,
996:                 format!("Failed to read {path_or_svg}: {io_err}"),
997:               ));
998:             }
999:           }
1000:         }
1001:       }
1002:       None => {
1003:         return Ok(DecodedBitmap {
1004:           bitmap: DecodeStatus::Empty,
1005:           width: self.width,
1006:           height: self.height,
1007:         });
1008:       }
1009:     };
1010:     let length = data_ref.len();
1011:     let mut width = self.width;
1012:     let mut height = self.height;
1013:     let bitmap = if data_ref.as_ref().starts_with(b"data:") {
1014:       let data_str = str::from_utf8(&data_ref)
1015:         .map_err(|e| Error::new(Status::InvalidArg, format!("Decode data url failed {e}")))?;
1016:       if let Some(base64_str) = data_str.split(',').next_back() {
1017:         let image_binary = STANDARD
1018:           .decode_to_vec(base64_str)
1019:           .map_err(|e| Error::new(Status::InvalidArg, format!("Decode data url failed {e}")))?;
1020:         if let Some(kind) = infer::get(&image_binary) {
1021:           if kind.matcher_type() == infer::MatcherType::Image {
1022:             DecodeStatus::Ok(BitmapInfo {
1023:               data: Bitmap::from_buffer(image_binary.as_ptr().cast_mut(), image_binary.len()),
1024:               is_svg: false,
1025:               decoded_image: None,
1026:             })
1027:           } else {
1028:             DecodeStatus::InvalidImage
1029:           }
1030:         } else {
1031:           DecodeStatus::InvalidImage
1032:         }
1033:       } else {
1034:         DecodeStatus::Empty
1035:       }
1036:     } else if libavif::is_avif(data_ref.as_ref()) {
1037:       // Check AVIF first - infer::get() may not recognize AVIF format
1038:       let avif_image = AvifImage::decode_from(data_ref.as_ref())
1039:         .map_err(|e| Error::new(Status::InvalidArg, format!("Decode avif image failed {e}")))?;
1040: 
1041:       let bitmap = Bitmap::from_image_data(
1042:         avif_image.data,
1043:         avif_image.width as usize,
1044:         avif_image.height as usize,
1045:         avif_image.row_bytes as usize,
1046:         (avif_image.row_bytes * avif_image.height) as usize,
1047:         ColorType::RGBA8888,
1048:         AlphaType::Premultiplied,
1049:       );
1050:       DecodeStatus::Ok(BitmapInfo {
1051:         data: bitmap,
1052:         is_svg: false,
1053:         decoded_image: Some(avif_image),
1054:       })
1055:     } else if if let Some(kind) = infer::get(&data_ref) {
1056:       kind.matcher_type() == infer::MatcherType::Image
1057:     } else {
1058:       false
1059:     } {
1060:       // Other image formats detected by infer (PNG, JPEG, GIF, WebP, etc.)
1061:       DecodeStatus::Ok(BitmapInfo {
1062:         data: Bitmap::from_buffer(data_ref.as_ptr().cast_mut(), length),
1063:         is_svg: false,
1064:         decoded_image: None,
1065:       })
1066:     } else if is_svg_image(&data_ref, length) {
1067:       let font = get_font().map_err(SkError::from)?;
1068:       if (self.width - -1.0).abs() > f64::EPSILON && (self.height - -1.0).abs() > f64::EPSILON {
1069:         if let Some(bitmap) = Bitmap::from_svg_data_with_custom_size(
1070:           data_ref.as_ptr(),
1071:           length,
1072:           self.width as f32,
1073:           self.height as f32,
1074:           self.color_space,
1075:           &font,
1076:         ) {
1077:           DecodeStatus::Ok(BitmapInfo {
1078:             data: bitmap,
1079:             is_svg: true,
1080:             decoded_image: None,
1081:           })
1082:         } else {
1083:           DecodeStatus::InvalidSvg
1084:         }
1085:       } else if let Some(bitmap) =
1086:         Bitmap::from_svg_data(data_ref.as_ptr(), length, self.color_space, &font)
1087:       {
1088:         if let Ok(bitmap) = bitmap {
1089:           DecodeStatus::Ok(BitmapInfo {
1090:             data: bitmap,
1091:             is_svg: true,
1092:             decoded_image: None,
1093:           })
1094:         } else {
1095:           DecodeStatus::InvalidSvg
1096:         }
1097:       } else {
1098:         DecodeStatus::Empty
1099:       }
1100:     } else {
1101:       DecodeStatus::InvalidImage
1102:     };
1103: 
1104:     if let DecodeStatus::Ok(ref b) = bitmap {
1105:       if (self.width - -1.0).abs() < f64::EPSILON
1106:         || (self.width - b.data.0.width as f64).abs() > f64::EPSILON
1107:       {
1108:         width = b.data.0.width as f64;
1109:       }
1110:       if (self.height - -1.0).abs() < f64::EPSILON
1111:         || (self.height - b.data.0.height as f64).abs() > f64::EPSILON
1112:       {
1113:         height = b.data.0.height as f64;
1114:       }
1115:     }
1116:     Ok(DecodedBitmap {
1117:       bitmap,
1118:       width,
1119:       height,
1120:     })
1121:   }
1122: 
1123:   fn resolve(&mut self, env: &'env Env, output: Self::Output) -> Result<Self::JsValue> {
1124:     let this: Object = self.this_ref.get_value(env)?;
1125:     let mut image_ptr = ptr::null_mut();
1126:     check_status!(
1127:       unsafe { sys::napi_unwrap(env.raw(), this.raw(), &mut image_ptr) },
1128:       "Failed to unwrap Image from this"
1129:     )?;
1130:     let self_mut = unsafe { Box::leak(Box::from_raw(image_ptr.cast::<Image>())) };
1131: 
1132:     // Check if this load has been superseded by a newer load
1133:     if self.generation != self_mut.load_generation {
1134:       // This is a stale load - silently abort without updating state or firing events
1135:       return ().into_unknown(env);
1136:     }
1137: 
1138:     self_mut.complete = true;
1139:     self_mut.bitmap = None;
1140: 
1141:     let mut err: Option<&str> = None;
1142: 
1143:     match output.bitmap {
1144:       DecodeStatus::Ok(bitmap) => {
1145:         // SUCCESS PATH: set dimensions, bitmap, currentSrc, file_content
1146:         self_mut.width = output.width;
1147:         self_mut.height = output.height;
1148:         self_mut.natural_width = output.width;
1149:         self_mut.natural_height = output.height;
1150: 
1151:         if let Some(data) = self.file_content.take() {
1152:           self_mut.file_content = Some(data);
1153:         }
1154: 
1155:         self_mut.src = self.data.take();
1156:         // If this was an HTTP URL load, override src with the original URL
1157:         if let Some(url) = self.original_url.take() {
1158:           self_mut.src = Some(Either::B(url));
1159:         }
1160:         // Update current_src based on what was actually loaded
1161:         self_mut.current_src = match &self_mut.src {
1162:           Some(Either::A(_)) => Some("[Buffer]".to_string()),
1163:           Some(Either::B(s)) => Some(s.clone()),
1164:           None => None,
1165:         };
