55: fn pixel<'a>(input: &'a str) -> Result<f32, ParseFilterError<'a>> {
56:   let (input, size) = take_till(|c: char| c.is_alpha())(input)?;
57:   let (_, unit) = take_till(|c| c == ')')(input)?;
58:   let size = size.trim().parse::<f32>()?;
59:   let mut size_px = size;
60:   match unit.trim() {
61:     "em" | "rem" | "pc" => {
62:       size_px = size * 16.0;
63:     }
64:     "pt" => {
65:       size_px = size * 4.0 / 3.0;
66:     }
67:     "px" => {
68:       size_px = size;
69:     }
70:     "in" => {
71:       size_px = size * 96.0;
72:     }
73:     "cm" => {
74:       size_px = size * 96.0 / 2.54;
75:     }
76:     "mm" => {
77:       size_px = size * 96.0 / 25.4;
78:     }
79:     "q" => {
80:       size_px = size * 96.0 / 25.4 / 4.0;
81:     }
82:     "%" => {
83:       size_px = size * 16.0 / 100.0;
84:     }
85:     "" => {
86:       if size_px != 0f32 {
87:         return Err(ParseFilterError::UnitParseError("[No unit assigned]"));
88:       }
89:     }
90:     _ => {
91:       return Err(ParseFilterError::UnitParseError(unit));
92:     }
93:   };
94: 
95:   Ok(size_px)
96: }
