189:   let (blurred_input, _) = tag("blur(")(input)?;
190: 
191:   let (blurred_input, pixel) = pixel_in_tuple(blurred_input)?;
192:   let (finished_input, _) = char(')')(blurred_input)?;
193:   Ok((finished_input.trim(), CssFilter::Blur(pixel)))
