196: #[allow(clippy::unnecessary_lazy_evaluations)]
197: fn drop_shadow_parser(input: &str) -> IResult<&str, CssFilter> {
198:   let (drop_shadow_input, _) = tag("drop-shadow(")(input)?;
199:   let drop_shadow_input = drop_shadow_input.trim();
200:   let (offset_x_output, offset_x) = map_res(take_until(" "), pixel).parse(drop_shadow_input)?;
201:   let offset_x_output = offset_x_output.trim();
202:   let (offset_y_output, offset_y) =
203:     map_res(take_till(|ch| ch == ' ' || ch == ')'), pixel).parse(offset_x_output)?;
204:   let offset_y_output = offset_y_output.trim();
205:   let (blur_radius_output, blur_radius) = map_res(take_till(|ch| ch == ' ' || ch == ')'), pixel)
206:     .parse(offset_y_output)
207:     .unwrap_or_else(|_: Err<Error<&str>>| (offset_y_output, 0.0f32));
208:   let blur_radius_output = blur_radius_output.trim();
209:   let is_rgb_fn = blur_radius_output.starts_with("rgb(") || blur_radius_output.starts_with("rgba(");
210:   let (shadow_color_output, shadow_color_str) =
211:     take_until(if is_rgb_fn { "))" } else { ")" })(blur_radius_output)?;
212:   let shadow_color_str = shadow_color_str.trim();
213:   static BLACK: RGBA<u8> = RGBA {
214:     r: 0,
215:     g: 0,
216:     b: 0,
217:     a: 255,
218:   };
219:   let shadow_color = if !shadow_color_str.is_empty() {
220:     let mut parser_input = ParserInput::new(shadow_color_str);
221:     let mut parser = Parser::new(&mut parser_input);
222:     let color = Color::parse(&mut parser).unwrap_or_else(|_| {
223:       Color::Rgba(RgbaLegacy {
224:         red: 0,
225:         green: 0,
226:         blue: 0,
227:         alpha: 1.0,
228:       })
229:     });
230:     match color {
231:       Color::Rgba(rgba) => {
232:         // Convert RgbaLegacy to RGBA<u8>
233:         RGBA {
234:           r: rgba.red,
235:           g: rgba.green,
236:           b: rgba.blue,
237:           a: (rgba.alpha * 255.0) as u8,
238:         }
239:       }
240:       Color::Hsl(hsl) => {
241:         let h = hsl.hue.unwrap_or(0.0) / 360.0;
242:         let s = hsl.saturation.unwrap_or(0.0);
243:         let l = hsl.lightness.unwrap_or(0.0);
244:         let a = hsl.alpha.unwrap_or(1.0);
245: 
246:         let (r, g, b) = hsl_to_rgb(h, s, l);
247: 
248:         RGBA {
249:           r: (r * 255.0) as u8,
250:           g: (g * 255.0) as u8,
251:           b: (b * 255.0) as u8,
252:           a: (a * 255.0) as u8,
253:         }
254:       }
255:       _ => BLACK,
256:     }
257:   } else {
258:     BLACK
259:   };
260:   let (mut drop_shadow_output, _) = char(')')(shadow_color_output.trim())?;
261:   if is_rgb_fn {
262:     let (trimmed_drop_shadow_output, _) = char(')')(drop_shadow_output)?;
263:     drop_shadow_output = trimmed_drop_shadow_output;
264:   }
265:   Ok((
266:     drop_shadow_output.trim(),
267:     CssFilter::DropShadow(offset_x, offset_y, blur_radius, shadow_color),
268:   ))
269: }
