295: pub(crate) fn css_filters_to_image_filter(filters: Vec<CssFilter>) -> Option<ImageFilter> {
296:   filters
297:     .into_iter()
298:     .try_fold(ImageFilter(ptr::null_mut()), |image_filter, f| match f {
299:       CssFilter::Blur(blur) => ImageFilter::make_blur(blur, blur, Some(&image_filter)),
300:       CssFilter::Brightness(brightness) => {
301:         let brightness = brightness.max(0.0);
302:         ImageFilter::make_image_filter(
303:           brightness,
304:           0.0,
305:           0.0,
306:           0.0,
307:           brightness,
308:           0.0,
309:           0.0,
310:           0.0,
311:           brightness,
312:           1.0,
313:           Some(&image_filter),
314:         )
315:       }
316:       CssFilter::Contrast(contrast) => {
317:         let amt = contrast.max(0.0);
318:         let mut ramp = [0u8; 256];
319:         ramp.iter_mut().take(256).enumerate().for_each(|(i, v)| {
320:           let orig = i as f32;
321:           *v = (127.0 + amt * (orig - 127.0)) as u8;
322:         });
323:         let ramp = Some(&ramp);
324:         ImageFilter::from_argb(None, ramp, ramp, ramp, Some(&image_filter))
325:       }
326:       CssFilter::DropShadow(offset_x, offset_y, blur_radius, shadow_color) => {
327:         let sigma = blur_radius / 2.0;
328:         if shadow_color.a == 0 {
329:           return None;
330:         }
331:         if blur_radius == 0f32 && offset_x == 0f32 && offset_y == 0f32 {
332:           return None;
333:         }
334:         ImageFilter::make_drop_shadow(
335:           offset_x,
336:           offset_y,
337:           sigma,
338:           sigma,
339:           ((shadow_color.a as u32) << 24)
340:             | ((shadow_color.r as u32) << 16)
341:             | ((shadow_color.g as u32) << 8)
342:             | shadow_color.b as u32,
343:           Some(&image_filter),
344:         )
345:       }
346:       CssFilter::Grayscale(amt) => {
347:         let amt = 1.0 - amt.clamp(0.0, 1.0);
348:         ImageFilter::make_image_filter(
349:           0.2126 + 0.7874 * amt,
350:           0.7152 - 0.7152 * amt,
351:           0.0722 - 0.0722 * amt,
352:           0.2126 - 0.2126 * amt,
353:           0.7152 + 0.2848 * amt,
354:           0.0722 - 0.0722 * amt,
355:           0.2126 - 0.2126 * amt,
356:           0.7152 - 0.7152 * amt,
357:           0.0722 + 0.9278 * amt,
358:           1.0,
359:           Some(&image_filter),
360:         )
361:       }
362:       CssFilter::HueRotate(angle) => {
363:         let cos = degrees_to_radians(angle).cos();
364:         let sin = degrees_to_radians(angle).sin();
365:         ImageFilter::make_image_filter(
366:           0.213 + cos * 0.787 - sin * 0.213,
367:           0.715 - cos * 0.715 - sin * 0.715,
368:           0.072 - cos * 0.072 + sin * 0.928,
369:           0.213 - cos * 0.213 + sin * 0.143,
370:           0.715 + cos * 0.285 + sin * 0.140,
371:           0.072 - cos * 0.072 - sin * 0.283,
372:           0.213 - cos * 0.213 - sin * 0.787,
373:           0.715 - cos * 0.715 + sin * 0.715,
374:           0.072 + cos * 0.928 + sin * 0.072,
375:           1.0,
376:           Some(&image_filter),
377:         )
378:       }
379:       CssFilter::Invert(amt) => {
380:         let amt = amt.clamp(0.0, 1.0);
381:         let mut ramp = [0u8; 256];
382:         ramp
383:           .iter_mut()
384:           .take(256)
385:           .enumerate()
386:           .map(|(i, v)| (i as f32, v))
387:           .for_each(|(i, val)| {
388:             let (orig, inv) = (i, 255.0 - i);
389:             *val = (orig * (1.0 - amt) + inv * amt) as u8;
390:           });
391:         let ramp = Some(&ramp);
392:         ImageFilter::from_argb(None, ramp, ramp, ramp, Some(&image_filter))
393:       }
394:       CssFilter::Opacity(opacity) => {
395:         let opacity = opacity.clamp(0.0, 1.0);
396:         ImageFilter::make_image_filter(
397:           1.0,
398:           0.0,
399:           0.0,
400:           0.0,
401:           1.0,
402:           0.0,
403:           0.0,
404:           0.0,
405:           1.0,
406:           opacity,
407:           Some(&image_filter),
408:         )
409:       }
410:       CssFilter::Saturate(amt) => {
411:         let amt = amt.max(0.0);
412:         ImageFilter::make_image_filter(
413:           0.2126 + 0.7874 * amt,
414:           0.7152 - 0.7152 * amt,
415:           0.0722 - 0.0722 * amt,
416:           0.2126 - 0.2126 * amt,
417:           0.7152 + 0.2848 * amt,
418:           0.0722 - 0.0722 * amt,
419:           0.2126 - 0.2126 * amt,
420:           0.7152 - 0.7152 * amt,
421:           0.0722 + 0.9278 * amt,
422:           1.0,
423:           Some(&image_filter),
424:         )
425:       }
426:       CssFilter::Sepia(amt) => {
427:         let amt = 1.0 - amt.clamp(0.0, 1.0);
428:         ImageFilter::make_image_filter(
429:           0.393 + 0.607 * amt,
430:           0.769 - 0.769 * amt,
431:           0.189 - 0.189 * amt,
432:           0.349 - 0.349 * amt,
433:           0.686 + 0.314 * amt,
434:           0.168 - 0.168 * amt,
