      PathOp::Intersect => SkPathOp::Intersect,
      PathOp::Union => SkPathOp::Union,
      PathOp::Xor => SkPathOp::Xor,
      PathOp::ReverseDifference => SkPathOp::ReverseDifference,
    }
  }
}

