  fn from(value: FillType) -> Self {
    match value {
      FillType::Winding => SkFillType::Winding,
      FillType::EvenOdd => SkFillType::EvenOdd,
      FillType::InverseWinding => SkFillType::InverseWinding,
      FillType::InverseEvenOdd => SkFillType::InverseEvenOdd,
